    INFER_ARGS='--model lab-model --ctx 100000 --split 55,45 --host 192.0.2.83'
  '';

  environment.systemPackages = with pkgs; [
    git
    tmux
    vim
    nano
    htop
    curl
    jq
    python3
    pciutils
    ethtool
    hdparm
    dmidecode
    lsof
    strace
    rsync
    bc
    tcpdump
    lshw
    screen
    mtr
    netcat-openbsd
