  users.groups = {
    ember.gid = 1000;
    probe.gid = 997;
    sudo.gid = 27;
    accel = {
      gid = 992;
      members = [ "ember" ];
    };
    i2c = {
      gid = 998;
      members = [ "ember" ];
    };
  };

  users.users.ember = {
